    "tStartMs": 1718,
    "dDurationMs": 1051,
    "segs": [ {
      "utf8": "但是我的意思就是說"
    } ]
  }, {
    "tStartMs": 5372,
    "dDurationMs": 1951,
    "segs": [ {
      "utf8": "就是因為我覺得火鍋的特色就是"
    } ]
  }, {
    "tStartMs": 11428,
    "dDurationMs": 1017,
    "segs": [ {
      "utf8": "我們不會說一個人"
    } ]
  }, {
    "tStartMs": 13646,
    "dDurationMs": 1068,
    "segs": [ {
      "utf8": "但每一個人都會有"
    } ]
  }, {
    "tStartMs": 16566,
    "dDurationMs": 951,
    "segs": [ {
      "utf8": "我的想法就是"
    } ]
  }, {
    "tStartMs": 20387,
    "dDurationMs": 1534,
    "segs": [ {
      "utf8": "就在描寫所謂的"
    } ]
  }, {
    "tStartMs": 25959,
    "dDurationMs": 1435,
    "segs": [ {
      "utf8": "然後我們好像被社會上"
    } ]
  }, {
    "tStartMs": 28561,
    "dDurationMs": 1452,
    "segs": [ {
      "utf8": "甚至我必須這麼說"
    } ]
  }, {
    "tStartMs": 30013,
    "dDurationMs": 1501,
    "segs": [ {
      "utf8": "連候選人推出來"
    } ]
  }, {
    "tStartMs": 33116,
    "dDurationMs": 867,
    "segs": [ {
      "utf8": "這一次又是"
    } ]
  }, {
    "tStartMs": 38471,
    "dDurationMs": 951,
    "segs": [ {
      "utf8": "各位觀眾朋友大家好 "
    } ]
  }, {
    "tStartMs": 39422,
    "dDurationMs": 1652,
    "segs": [ {
      "utf8": "我是旅行長工頭堅"
    } ]
  }, {
    "tStartMs": 41074,
    "dDurationMs": 1001,
    "segs": [ {
      "utf8": "我們這個頻道呢"
    } ]
  }, {
    "tStartMs": 42075,
    "dDurationMs": 1385,
    "segs": [ {
      "utf8": "之前曾經有一段時間"
    } ]
  }, {
    "tStartMs": 43460,
    "dDurationMs": 1001,
    "segs": [ {
      "utf8": "大家可能還記得"
    } ]
  }, {
    "tStartMs": 44461,
    "dDurationMs": 1201,
    "segs": [ {
      "utf8": "做過Podcast"
    } ]
  }, {
    "tStartMs": 45662,
    "dDurationMs": 1802,
    "segs": [ {
      "utf8": "對談等等的形式"
    } ]
  }, {
    "tStartMs": 47464,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "但後來因為自己真的太忙了"
    } ]
  }, {
    "tStartMs": 49466,
    "dDurationMs": 2402,
    "segs": [ {
      "utf8": "一直去日本取材出外景"
    } ]
  }, {
    "tStartMs": 51868,
    "dDurationMs": 1218,
    "segs": [ {
      "utf8": "所以停了一段時間"
    } ]
  }, {
    "tStartMs": 53086,
    "dDurationMs": 2869,
    "segs": [ {
      "utf8": "那最近我跟製作人就思考了一下"
    } ]
  }, {
    "tStartMs": 55955,
    "dDurationMs": 2386,
    "segs": [ {
      "utf8": "我們可能會恢復這種對談的形態"
    } ]
  }, {
    "tStartMs": 58341,
    "dDurationMs": 2469,
    "segs": [ {
      "utf8": "等於是恢復對談形態的第一集"
    } ]
  }, {
    "tStartMs": 60810,
    "dDurationMs": 2703,
    "segs": [ {
      "utf8": "我們請到一位非常特別的來賓"
    } ]
  }, {
    "tStartMs": 63513,
    "dDurationMs": 1001,
    "segs": [ {
      "utf8": "我待會再介紹他"
    } ]
  }, {
    "tStartMs": 64514,
    "dDurationMs": 1151,
    "segs": [ {
      "utf8": "我先跟大家講一下"
    } ]
  }, {
    "tStartMs": 65665,
    "dDurationMs": 1285,
    "segs": [ {
      "utf8": "我們今天要談什麼"
    } ]
  }, {
    "tStartMs": 66950,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "今天這個議題是說"
    } ]
  }, {
    "tStartMs": 68952,
    "dDurationMs": 1551,
    "segs": [ {
      "utf8": "《台北的天空》 這首歌 "
    } ]
  }, {
    "tStartMs": 70503,
    "dDurationMs": 1318,
    "segs": [ {
      "utf8": "很多人可能聽過"
    } ]
  }, {
    "tStartMs": 71821,
    "dDurationMs": 1352,
    "segs": [ {
      "utf8": "它是1985年的 "
    } ]
  }, {
    "tStartMs": 73173,
    "dDurationMs": 2235,
    "segs": [ {
      "utf8": "到今年已經41年了"
    } ]
  }, {
    "tStartMs": 75408,
    "dDurationMs": 1802,
    "segs": [ {
      "utf8": "然後林強的 《向前走》"
    } ]
  }, {
    "tStartMs": 77210,
    "dDurationMs": 3070,
    "segs": [ {
      "utf8": "1990年到今年已經36年了"
    } ]
  }, {
    "tStartMs": 80280,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "這40年來台北蓋了捷運 "
    } ]
  }, {
    "tStartMs": 82282,
    "dDurationMs": 834,
    "segs": [ {
      "utf8": "蓋了101"
    } ]
  }, {
    "tStartMs": 83116,
    "dDurationMs": 2152,
    "segs": [ {
      "utf8": "東區起來好像又沒落了"
    } ]
  }, {
    "tStartMs": 85268,
    "dDurationMs": 1552,
    "segs": [ {
      "utf8": "南港內湖整個都變了樣"
    } ]
  }, {
    "tStartMs": 86820,
    "dDurationMs": 2602,
    "segs": [ {
      "utf8": "可是我們要唱台北的時候"
    } ]
  }, {
    "tStartMs": 89422,
    "dDurationMs": 2002,
    "segs": [ {
      "utf8": "我們還是要回去唱那兩首"
    } ]
  }, {
    "tStartMs": 91424,
    "dDurationMs": 2786,
    "segs": [ {
      "utf8": "所以我們今天要來探討一個問題"
    } ]
  }, {
    "tStartMs": 94210,
    "dDurationMs": 2519,
    "segs": [ {
      "utf8": "就是說在台北住了40年之後"
    } ]
  }, {
    "tStartMs": 96729,
    "dDurationMs": 1685,
    "segs": [ {
      "utf8": "我們到底算不算台北人"
    } ]
  }, {
    "tStartMs": 98414,
    "dDurationMs": 2853,
    "segs": [ {
      "utf8": "然後我們接下來要唱什麼樣的歌"
    } ]
  }, {
    "tStartMs": 101267,
    "dDurationMs": 1719,
    "segs": [ {
      "utf8": "今天這位來賓就是"
    } ]
  }, {
    "tStartMs": 102986,
    "dDurationMs": 3136,
    "segs": [ {
      "utf8": "台北市長候選人沈伯洋 教授"
    } ]
  }, {
    "tStartMs": 106122,
    "dDurationMs": 801,
    "segs": [ {
      "utf8": "大家好"
    } ]
  }, {
    "tStartMs": 106923,
    "dDurationMs": 1635,
    "segs": [ {
      "utf8": "Puma老師 "
    } ]
  }, {
    "tStartMs": 108558,
    "dDurationMs": 1652,
    "segs": [ {
      "utf8": "我應該叫你Puma老師"
    } ]
  }, {
    "tStartMs": 110210,
    "dDurationMs": 2702,
    "segs": [ {
      "utf8": "用這樣的Puma老師這個角度"
    } ]
  }, {
    "tStartMs": 112912,
    "dDurationMs": 501,
    "segs": [ {
      "utf8": "好"
    } ]
  }, {
    "tStartMs": 113413,
    "dDurationMs": 2602,
    "segs": [ {
      "utf8": "這個剛才我們一開始聊到的"
    } ]
  }, {
    "tStartMs": 116015,
    "dDurationMs": 2937,
    "segs": [ {
      "utf8": "就是說一些整個世代人的共同記憶"
    } ]
  }, {
    "tStartMs": 118952,
    "dDurationMs": 1718,
    "segs": [ {
      "utf8": "那我覺得在談這個"
    } ]
  }, {
    "tStartMs": 120670,
    "dDurationMs": 1952,
    "segs": [ {
      "utf8": "比較嚴肅的問題之前"
    } ]
